import{_ as t,a}from"./chunks/public-page.Cis11Pa3.js";import{_ as r,c as s,o as n,a2 as i}from"./chunks/framework.PGES7OoM.js";const o="/assets/send-from-curvy.DRqgtrwp.png",f=JSON.parse('{"title":"Make Your Existing Assets Private","description":"","frontmatter":{"rawMarkdown":"# Make Your Existing Assets Private\\n\\nTo use Curvy for private payments, you first need to get some assets into your Curvy App.\\n\\nThis process is commonly referred to as \\"shielding\\", as Curvy shields your funds from prying eyes.\\n\\n## From the Curvy app\\n\\nThe easiest way to shield funds is to connect your existing wallet by clicking the *Fund from a connected wallet*\\nin the bottom right corner of the right sidebar in the Curvy App.\\n\\n![Send from Curvy](send-from-curvy.png)\\n\\n## From an ENS compatible wallet\\n\\nIf you are using a wallet that supports Ethereum Name Service, such as MetaMask or Rabby,\\nyou can just enter your Curvy ID as the recipient for a new transaction:\\n\\n![Using Curvy name in Metamask](ens-metamask.png)\\n\\n## Receiving from other wallets\\n\\nTo receive funds from other wallets, you can simply instruct the sender to open the following URL:\\n\\n```\\nhttps://your-curvy-id.curvy.name\\n```\\n\\nThis will create a one-time private receiving address to which they can send the funds.\\n\\nAn example with [https://travica.curvy.name](https://travica.curvy.name):\\n\\n![Public page](public-page.png)\\n","rawMarkdownPath":"/_raw/for-users/make-your-existing-assets-private.md","rawMarkdownTitle":"Make Your Existing Assets Private","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/make-your-existing-assets-private.md"},"headers":[],"relativePath":"for-users/make-your-existing-assets-private.md","filePath":"for-users/make-your-existing-assets-private.md","lastUpdated":1773768298000}'),p={name:"for-users/make-your-existing-assets-private.md"};function u(l,e,c,m,h,d){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="make-your-existing-assets-private" tabindex="-1">Make Your Existing Assets Private <a class="header-anchor" href="#make-your-existing-assets-private" aria-label="Permalink to &quot;Make Your Existing Assets Private&quot;">​</a></h1><p>To use Curvy for private payments, you first need to get some assets into your Curvy App.</p><p>This process is commonly referred to as &quot;shielding&quot;, as Curvy shields your funds from prying eyes.</p><h2 id="from-the-curvy-app" tabindex="-1">From the Curvy app <a class="header-anchor" href="#from-the-curvy-app" aria-label="Permalink to &quot;From the Curvy app&quot;">​</a></h2><p>The easiest way to shield funds is to connect your existing wallet by clicking the <em>Fund from a connected wallet</em> in the bottom right corner of the right sidebar in the Curvy App.</p><p><img src="'+o+'" alt="Send from Curvy"></p><h2 id="from-an-ens-compatible-wallet" tabindex="-1">From an ENS compatible wallet <a class="header-anchor" href="#from-an-ens-compatible-wallet" aria-label="Permalink to &quot;From an ENS compatible wallet&quot;">​</a></h2><p>If you are using a wallet that supports Ethereum Name Service, such as MetaMask or Rabby, you can just enter your Curvy ID as the recipient for a new transaction:</p><p><img src="'+t+'" alt="Using Curvy name in Metamask"></p><h2 id="receiving-from-other-wallets" tabindex="-1">Receiving from other wallets <a class="header-anchor" href="#receiving-from-other-wallets" aria-label="Permalink to &quot;Receiving from other wallets&quot;">​</a></h2><p>To receive funds from other wallets, you can simply instruct the sender to open the following URL:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-curvy-id.curvy.name</span></span></code></pre></div><p>This will create a one-time private receiving address to which they can send the funds.</p><p>An example with <a href="https://travica.curvy.name" target="_blank" rel="noreferrer">https://travica.curvy.name</a>:</p><p><img src="'+a+'" alt="Public page"></p>',15)])])}const g=r(p,[["render",u]]);export{f as __pageData,g as default};
